// Sends report emails to shop owners.
import { saveReport } from './store.js';
import { sendMail } from './mail.js';
import { renderCorrection, renderDaily, renderWeekly } from './report_render.js';

async function sendReport(shop, kind, period, subject, html) {
  await saveReport(`${kind}-${shop.id}-${period}`, html);
  await sendMail(shop.email, subject, html);
  return { shopId: shop.id, kind, bytes: html.length };
}

export async function sendDailyReport(shop, rows, day) {
  return sendReport(shop, 'daily', day, `Your report for ${day}`, renderDaily(shop, rows, day));
}

export async function sendWeeklyReport(shop, rows, weekStart) {
  return sendReport(shop, 'weekly', weekStart, `Your report for the week of ${weekStart}`, renderWeekly(shop, rows, weekStart));
}

export async function sendCorrection(shop, rows, day, note) {
  return sendReport(shop, 'correction', day, `Corrected report for ${day}`, renderCorrection(shop, rows, day, note));
}
